/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
/* ========================================================================== */
/* BFUSION Status Trend Sparkline v1.1 — Compact D3 Layout                   */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  display: block;
  overflow: hidden;
  background: var(--bf-bg, #FFFFFF);
}
.bfusion-chart-wrap svg {
  display: block;
}
/* ========================================================================== */
/* Interactive Dots                                                           */
/* ========================================================================== */
.bfusion-dot {
  transition: opacity 0.12s ease;
}
.bfusion-dot:hover {
  filter: brightness(1.12);
}
/* ========================================================================== */
/* Rich Tooltip                                                               */
/* ========================================================================== */
.bfusion-tooltip {
  display: none;
  position: absolute;
  background: rgba(28, 28, 28, 0.92);
  color: #fff;
  padding: 7px 10px;
  border-radius: 5px;
  font-size: 11px;
  line-height: 1.5;
  pointer-events: none;
  z-index: 100;
  max-width: 240px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(4px);
}
.bfusion-tooltip .tt-title {
  font-weight: 600;
  font-size: 11.5px;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-tooltip .tt-row {
  font-size: 10.5px;
  color: #ddd;
}
.bfusion-tooltip .tt-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 4px;
  vertical-align: middle;
}
.bfusion-tooltip .tt-muted {
  color: var(--bf-muted, #667079);
  font-style: italic;
}
.bfusion-tooltip .tt-comment {
  margin-top: 4px;
  font-size: 10px;
  color: var(--bf-muted, #667079);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 4px;
  max-height: 60px;
  overflow: hidden;
}
/* ========================================================================== */
/* Responsive Landing Page Framework                                          */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
